import * as fs from 'node:fs';

import { normalizeRelativePath } from './filesystem';
import {
  type GeneratedFilesManifest,
  GENERATOR_NAME,
  MANIFEST_VERSION,
  type ManifestFileEntry,
} from './types';

const LEGACY_GENERATED_MARKERS = [
  '@generated by @constructive-io/graphql-codegen',
  '@constructive-io/graphql-codegen - DO NOT EDIT',
];

function isManifest(value: unknown): value is GeneratedFilesManifest {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<GeneratedFilesManifest>;
  if (
    candidate.version !== MANIFEST_VERSION ||
    candidate.generator !== GENERATOR_NAME ||
    !candidate.files ||
    typeof candidate.files !== 'object' ||
    Array.isArray(candidate.files)
  ) {
    return false;
  }

  return Object.entries(candidate.files).every(([filePath, entry]) => {
    try {
      if (normalizeRelativePath(filePath) !== filePath) return false;
    } catch {
      return false;
    }
    return (
      !!entry &&
      typeof entry === 'object' &&
      typeof entry.sha256 === 'string' &&
      /^[a-f0-9]{64}$/.test(entry.sha256)
    );
  });
}

export function readManifest(manifestPath: string): {
  manifest: GeneratedFilesManifest;
  content?: string;
} {
  if (!fs.existsSync(manifestPath)) {
    return {
      manifest: {
        version: MANIFEST_VERSION,
        generator: GENERATOR_NAME,
        files: {},
      },
    };
  }

  const content = fs.readFileSync(manifestPath, 'utf8');
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    throw new Error(
      `Generated ownership manifest is not valid JSON: ${manifestPath}`,
    );
  }

  if (!isManifest(parsed)) {
    throw new Error(
      `Generated ownership manifest has an unsupported or invalid shape: ${manifestPath}`,
    );
  }

  return { manifest: parsed, content };
}

export function isLegacyGenerated(content: Buffer): boolean {
  const prefix = content.subarray(0, 4096).toString('utf8');
  return LEGACY_GENERATED_MARKERS.some((marker) => prefix.includes(marker));
}

export function createManifestContent(
  files: Record<string, ManifestFileEntry>,
): string {
  const sortedFiles = Object.fromEntries(
    Object.entries(files).sort(([left], [right]) => left.localeCompare(right)),
  );
  return `${JSON.stringify(
    {
      version: MANIFEST_VERSION,
      generator: GENERATOR_NAME,
      files: sortedFiles,
    } satisfies GeneratedFilesManifest,
    null,
    2,
  )}\n`;
}
